schema.content:
Table "country" {
  "country_id" INTEGER [pk, not null]
  "country_iso_code" TEXT
  "country_name" TEXT
}

Table "department" {
  "department_id" INTEGER [pk, not null]
  "department_name" TEXT
}

Table "gender" {
  "gender_id" INTEGER [pk, not null]
  "gender" TEXT
}

Table "genre" {
  "genre_id" INTEGER [pk, not null]
  "genre_name" TEXT
}

Table "keyword" {
  "keyword_id" INTEGER [pk, not null]
  "keyword_name" TEXT
}

Table "language" {
  "language_id" INTEGER [pk, not null]
  "language_code" TEXT
  "language_name" TEXT
}

Table "language_role" {
  "role_id" INTEGER [pk, not null]
  "language_role" TEXT
}

Table "movie" {
  "movie_id" INTEGER [pk, not null]
  "title" TEXT
  "budget" INTEGER
  "homepage" TEXT
  "overview" TEXT
  "popularity" REAL
  "release_date" DATE
  "revenue" INTEGER
  "runtime" INTEGER
  "movie_status" TEXT
  "tagline" TEXT
  "vote_average" REAL
  "vote_count" INTEGER
}

Table "movie_cast" {
  "movie_id" INTEGER
  "person_id" INTEGER
  "character_name" TEXT
  "gender_id" INTEGER
  "cast_order" INTEGER
}

Table "movie_company" {
  "movie_id" INTEGER
  "company_id" INTEGER
}

Table "movie_crew" {
  "movie_id" INTEGER
  "person_id" INTEGER
  "department_id" INTEGER
  "job" TEXT
}

Table "movie_genres" {
  "movie_id" INTEGER
  "genre_id" INTEGER
}

Table "movie_keywords" {
  "movie_id" INTEGER
  "keyword_id" INTEGER
}

Table "movie_languages" {
  "movie_id" INTEGER
  "language_id" INTEGER
  "language_role_id" INTEGER
}

Table "person" {
  "person_id" INTEGER [pk, not null]
  "person_name" TEXT
}

Table "production_company" {
  "company_id" INTEGER [pk, not null]
  "company_name" TEXT
}

Table "production_country" {
  "movie_id" INTEGER
  "country_id" INTEGER
}



Ref: "movie_genres"."movie_id" > "movie"."movie_id"

Ref: "movie_genres"."genre_id" > "genre"."genre_id"

Ref: "movie_languages"."language_role_id" > "language_role"."role_id"

Ref: "movie_languages"."movie_id" > "movie"."movie_id"

Ref: "movie_languages"."language_id" > "language"."language_id"

Ref: "movie_crew"."person_id" > "person"."person_id"

Ref: "movie_crew"."movie_id" > "movie"."movie_id"

Ref: "movie_crew"."department_id" > "department"."department_id"

Ref: "production_country"."movie_id" > "movie"."movie_id"

Ref: "production_country"."country_id" > "country"."country_id"

Ref: "movie_cast"."person_id" > "person"."person_id"

Ref: "movie_cast"."movie_id" > "movie"."movie_id"

Ref: "movie_cast"."gender_id" > "gender"."gender_id"
